<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Fields;

use Throwable;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigCollectNonEditableFields;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class FixTenantExcludingRoot
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(SmtpOutboundConfigCollectNonEditableFields $event): SmtpOutboundConfigCollectNonEditableFields
    {
        $this->logDebug("Check FixTenantExcludingRoot Smtp outbound config");
        $span = $this->startSpan("Check FixTenantExcludingRoot Smtp outbound config");
        try {
            $identity = $this->context->getIdentity();
            if (!($identity->hasScope("platform:global_access"))) {
                $event->withAll(['tenant']);
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
